protocol Service { func call(_ req: Request) async throws -> Response }

struct Gate: Service {                          // one gate per boundary
    let next: any Service
    let rule: Rule
    func call(_ req: Request) async throws -> Response {
        let id = try await verify(req)           // this gate's own evidence
        guard rule.allows(id, req) else { throw Denied() }   // fail closed
        return try await next.call(req)          // delegate inward
    }
}
